BEGIN READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT coalesce(json_agg(q),'[]'::json) FROM (
 SELECT id,topic_id,created_at,subject,message_id,length(body) AS body_length,left(body,8000) AS body
 FROM messages WHERE topic_id=30796 ORDER BY created_at,id LIMIT 20
) q;
SELECT coalesce(json_agg(q),'[]'::json) FROM (
 SELECT id,message_id,file_name,content_type,length(body) AS stored_body_length
 FROM attachments WHERE message_id IN (SELECT id FROM messages WHERE topic_id=30796 ORDER BY created_at,id LIMIT 20)
 ORDER BY id LIMIT 30
) q;
COMMIT;
